"""scripts/check_requirements_lock.py: requirements.txt edits must reach the lock."""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
SCRIPT = REPO / "scripts" / "check_requirements_lock.py"

LOCK = """\
# This file was autogenerated by uv via the following command:
#    uv pip compile --generate-hashes --python-version 3.12 backend/requirements.txt -o backend/requirements.lock
fastapi==0.143.1 \\
    --hash=sha256:aaaa
    # via -r backend/requirements.txt
numpy==2.3.1 \\
    --hash=sha256:bbbb
uvicorn==0.54.0 \\
    --hash=sha256:cccc
"""


def _check(tmp_path: Path, requirements: str) -> subprocess.CompletedProcess[str]:
    req = tmp_path / "requirements.txt"
    lock = tmp_path / "requirements.lock"
    req.write_text(requirements)
    lock.write_text(LOCK)
    return subprocess.run(
        [sys.executable, str(SCRIPT), str(req), str(lock)],
        capture_output=True,
        text=True,
        check=False,
    )


def test_a_lock_that_satisfies_every_direct_requirement_passes(tmp_path):
    out = _check(
        tmp_path,
        "# comment\n-r other.txt\nfastapi==0.143.1\nuvicorn[standard]==0.54.0\n"
        "numpy>=2.0,<3  # range\n",
    )
    assert out.returncode == 0, out.stderr


def test_a_bumped_pin_without_a_new_lock_fails(tmp_path):
    """What a Dependabot pull request against requirements.txt alone looks like."""
    out = _check(tmp_path, "fastapi==0.144.0\nnumpy>=2.0,<3\n")
    assert out.returncode == 1
    assert "fastapi" in out.stderr and "0.143.1" in out.stderr
    assert "uv pip compile" in out.stderr


def test_a_new_dependency_missing_from_the_lock_fails(tmp_path):
    out = _check(tmp_path, "fastapi==0.143.1\nhttpx==0.28.1\n")
    assert out.returncode == 1
    assert "httpx" in out.stderr


def test_the_committed_lock_is_current():
    out = subprocess.run(
        [sys.executable, str(SCRIPT)], capture_output=True, text=True, check=False
    )
    assert out.returncode == 0, out.stderr
